-1.0,    0.0, 0.0 ,    -2.0/3.0,
1.0,    0.0, 0.0 ,    -2.0/3.0
};
sampler sampler_rand01;
shader_body
{
vec2 d = (vec2(1.0)/uTexSize) * 8.0;
float dx = ( GetBlur1(uv.yx+vec2( 1.0 , 0.0 )*d)-GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy ).y;
float dy = ( GetBlur1(uv.yx+vec2( 0.0 , 1.0 )*d)-GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy ).y;
vec2 uv_y = uv+vec2(dy,dx)*0.55;
vec2 uv_y2 = (uv_y*1.25)-.125;
ret = mix(ret,1.0 - ret,.7*GetBlur1(uv_y)+.2*GetPixel(uv.yx).xy);
ret = mix(ret,ret-.1*GetBlur3(uv_y)+.1*GetBlur1(uv_y2).xy+.42*GetPixel(uv_y),.25);
//ret *= .75;
ret *= clamp01(length(ret-0.5) * 5.0);
//ret = ret.xy;
ret = lum(ret);
ret += 1.25;
ret *= ret*.45;
vec3 mask = GetBlur3(uv)-GetBlur1(uv).xy-.25*GetBlur2(uv_y);
ret *= mix(ret,1.3*ret*mask,pow(hue_shader.zxy,ret));
ret *=1;
vec3 a_varaible = 0;
for(int i=0;i<5;i++)
a_varaible += samples[i].w*texture(sampler_rand01,ret*0.1+
vec2(samples[i].x*(1.0 / uTexSize.x),
samples[i].y*(1.0 / uTexSize.y)))*0.2;
ret = a_varaible;
ret = vec3( 1.0 ) - 2.0*(1.0 - ret)*ret - GetBlur3(uv);
}

